package com.devsphere.ui;

import com.devsphere.model.*;import com.devsphere.service.*;
import javax.swing.*;import java.awt.*;import java.sql.SQLException;import java.util.List;

public class IssueDetailsDialog extends JDialog{
 private final IssueService service;private final Session session;private final long issueId;private final Runnable changed;private Issue issue;private final JLabel heading=new JLabel();private final JTextArea info=new JTextArea();private final DefaultListModel<String> comments=new DefaultListModel<>(),activity=new DefaultListModel<>();private final JPanel actions=new JPanel();
 public IssueDetailsDialog(Component parent,IssueService service,Session session,long issueId,Runnable changed){super(SwingUtilities.getWindowAncestor(parent),"Issue details",ModalityType.APPLICATION_MODAL);this.service=service;this.session=session;this.issueId=issueId;this.changed=changed;setSize(800,650);setLocationRelativeTo(parent);add(build());reload();}
 private JPanel build(){JPanel p=new JPanel(new BorderLayout(0,8));p.setBorder(BorderFactory.createEmptyBorder(18,22,18,22));heading.setFont(new Font("SansSerif",Font.BOLD,23));heading.setForeground(new Color(24,39,75));p.add(heading,BorderLayout.NORTH);info.setEditable(false);info.setLineWrap(true);info.setWrapStyleWord(true);info.setRows(6);p.add(new JScrollPane(info),BorderLayout.CENTER);JPanel bottom=new JPanel(new GridLayout(1,2,12,0));JPanel cp=new JPanel(new BorderLayout());cp.add(new JLabel("Comments"),BorderLayout.NORTH);cp.add(new JScrollPane(new JList<>(comments)),BorderLayout.CENTER);JPanel ap=new JPanel(new BorderLayout());ap.add(new JLabel("Activity"),BorderLayout.NORTH);ap.add(new JScrollPane(new JList<>(activity)),BorderLayout.CENTER);bottom.add(cp);bottom.add(ap);JPanel south=new JPanel(new BorderLayout());south.add(bottom,BorderLayout.CENTER);actions.setLayout(new FlowLayout());south.add(actions,BorderLayout.SOUTH);p.add(south,BorderLayout.SOUTH);return p;}
 private void reload(){try{issue=service.get(session,issueId);heading.setText("#"+issue.id()+" "+issue.title());info.setText("Project: "+issue.projectName()+"\nType: "+issue.issueType()+"\nPriority: "+issue.priority()+"\nStatus: "+issue.status()+"\nReporter: "+issue.reporterUsername()+"\nAssignee: "+(issue.assigneeUsername()==null?"Unassigned":issue.assigneeUsername())+"\nDue: "+(issue.dueDate()==null?"None":issue.dueDate())+"\n\n"+(issue.description()==null?"":issue.description()));comments.clear();for(IssueComment c:service.comments(session,issueId))comments.addElement(c.authorUsername()+" ("+c.createdAt()+"): "+c.comment());activity.clear();for(IssueActivity a:service.activity(session,issueId))activity.addElement(a.createdAt()+" - "+a.actorUsername()+" - "+a.actionType()+" "+(a.oldValue()==null?"":a.oldValue()+" -> "+a.newValue()));actions.removeAll();JButton comment=new JButton("Add comment");comment.addActionListener(e->addComment());JButton update=new JButton("Update issue");update.addActionListener(e->update());actions.add(comment);actions.add(update);actions.revalidate();actions.repaint();}catch(Exception e){show(e.getMessage());dispose();}}
 private void addComment(){String text=JOptionPane.showInputDialog(this,"Comment:");if(text==null)return;try{service.comment(session,issueId,text);changed.run();reload();}catch(Exception e){show(e.getMessage());}}
 private void update(){try{java.util.List<ProjectMember> members=service.members(session,issue.projectId());IssueUpdate u=IssueFormDialog.show(this,issue,members);if(u!=null){service.update(session,issueId,u);changed.run();reload();}}catch(Exception e){show(e.getMessage());}}
 private void show(String m){JOptionPane.showMessageDialog(this,m,"Issue",JOptionPane.WARNING_MESSAGE);}
}
